    #[test]
    fn unicode_xid_continue_property_work_deduplication_and_contracts() {
        // Tags 70/71 follow the widened mask boundary and coexist with earlier bits.
        for sets in [false, true] {
            for (source, points) in [
                (
                    r"[\P{XID_Continue}\p{ASCII}\p{Bidi_M}]",
                    &[(0x41, true), (0x28, true), (0x200c, false), (0x3b9, false)][..],
                ),
                (
                    r"[\p{XID_Continue}\P{DI}]",
                    &[
                        (0x41, true),
                        (0x200c, true),
                        (0xfeff, false),
                        (0x1f600, true),
                    ][..],
                ),
                (
                    r"[\p{XID_Continue}\p{DI}\p{ASCII}]",
                    &[
                        (0x41, true),
                        (0x200c, true),
                        (0xfeff, true),
                        (0x1f600, false),
                    ][..],
                ),
                (
                    r"[^\P{ASCII}\p{XID_Continue}\P{Bidi_M}]",
                    &[
                        (0x41, false),
                        (0x28, true),
                        (0x200c, false),
                        (0x1f600, false),
                    ][..],
                ),
            ] {
                let plan = RegExpUnicodeClassMatcher::compile_with_flags(
                    &JsString::from(source),
                    sets,
                    false,
                    false,
                )
                .unwrap();
                for &(point, expected) in points {
                    assert_eq!(plan.matches(point), expected, "{source} U+{point:X}");
                }
            }
        }

        let source =
            JsString::from(format!("[{}]", r"\p{XIDC}\P{XID_Continue}".repeat(10000)).as_str());
        let plan =
            RegExpUnicodeClassMatcher::compile_with_flags(&source, true, true, false).unwrap();
        assert!(!plan.ranges.is_empty());
        assert_eq!(
            plan.clone().find(&JsString::from("😀"), 1, true),
            Some(0..2)
        );
        for source in [r"^\P{XIDC}$", r"^[\P{XID_Continue}K]$"] {
            let source = JsString::from(source);
            let class = source.code_units().contains(&0x5b);
            let mut calls = 0;
            let charge = |_| {
                calls += 1;
                Ok::<(), ()>(())
            };
            let plan = if class {
                RegExpUnicodeClassMatcher::compile_with_flags_and_work(
                    &source, true, true, true, charge,
                )
            } else {
                RegExpUnicodeClassMatcher::compile_binary_property_with_flags_and_work(
                    &source, true, true, true, charge,
                )
            }
            .unwrap()
            .unwrap();
            let count = calls;
            for fail in 1..=count {
                let mut n = 0;
                let charge = |_| {
                    n += 1;
                    if fail == n { Err(()) } else { Ok(()) }
                };
                let result = if class {
                    RegExpUnicodeClassMatcher::compile_with_flags_and_work(
                        &source, true, true, true, charge,
                    )
                } else {
                    RegExpUnicodeClassMatcher::compile_binary_property_with_flags_and_work(
                        &source, true, true, true, charge,
                    )
                };
                assert!(result.is_err());
            }
            assert_eq!(
                plan.find(&JsString::from("\u{41}\n😀\n"), 0, false),
                Some(2..4)
            );
        }
        for source in [
            r"[\p{XIDC}--A]",
            r"[\p{XIDC}&&A]",
            r"[[\p{XIDC}]]",
            r"[A-\p{XIDC}]",
            r"[\p{XIDC}-A]",
            r"[\p{Assigned}]",
        ] {
            assert!(
                RegExpUnicodeClassMatcher::compile_with_flags(
                    &JsString::from(source),
                    true,
                    true,
                    false
                )
                .is_none()
            );
        }
        assert!(
            RegExpUnicodeClassMatcher::compile_binary_property_with_flags(
                &JsString::from(r"[\p{XIDC}]"),
                true,
                true,
                false
            )
            .is_none()
        );
    }
