    #[test]
    fn unicode_uppercase_property_work_deduplication_and_contracts() {
        // New tags 78/79 must coexist with earlier low and high mask bits.
        for sets in [false, true] {
            let union = RegExpUnicodeClassMatcher::compile_with_flags(
                &JsString::from(r"[\p{ASCII}\p{Bidi_M}\p{Uppercase}]"),
                sets,
                false,
                false,
            )
            .unwrap();
            for (point, expected) in [
                (0x41, true),
                (0x28, true),
                (0x41, true),
                (0x42, true),
                (0x1d400, true),
                (0x1f600, false),
            ] {
                assert_eq!(union.matches(point), expected, "U+{point:X}");
            }
            let complement = RegExpUnicodeClassMatcher::compile_with_flags(
                &JsString::from(r"[^\P{ASCII}\p{Uppercase}\P{Bidi_M}]"),
                sets,
                false,
                false,
            )
            .unwrap();
            for (point, expected) in [
                (0x41, false),
                (0x28, true),
                (0x41, false),
                (0x42, false),
                (0x1d400, false),
                (0x1f600, false),
            ] {
                assert_eq!(complement.matches(point), expected, "U+{point:X}");
            }
        }

        let source =
            JsString::from(format!("[{}]", r"\p{Upper}\P{Uppercase}".repeat(10000)).as_str());
        let plan =
            RegExpUnicodeClassMatcher::compile_with_flags(&source, true, true, false).unwrap();
        assert!(!plan.ranges.is_empty());
        assert_eq!(
            plan.clone().find(&JsString::from("😀"), 1, true),
            Some(0..2)
        );
        for source in [r"^\P{Upper}$", r"^[\P{Uppercase}K]$"] {
            let source = JsString::from(source);
            let class = source.code_units().contains(&0x5b);
            let mut calls = 0;
            let charge = |_| {
                calls += 1;
                Ok::<(), ()>(())
            };
            let plan = if class {
                RegExpUnicodeClassMatcher::compile_with_flags_and_work(
                    &source, true, true, true, charge,
                )
            } else {
                RegExpUnicodeClassMatcher::compile_binary_property_with_flags_and_work(
                    &source, true, true, true, charge,
                )
            }
            .unwrap()
            .unwrap();
            let count = calls;
            for fail in 1..=count {
                let mut n = 0;
                let charge = |_| {
                    n += 1;
                    if fail == n { Err(()) } else { Ok(()) }
                };
                let result = if class {
                    RegExpUnicodeClassMatcher::compile_with_flags_and_work(
                        &source, true, true, true, charge,
                    )
                } else {
                    RegExpUnicodeClassMatcher::compile_binary_property_with_flags_and_work(
                        &source, true, true, true, charge,
                    )
                };
                assert!(result.is_err());
            }
            assert_eq!(
                plan.find(&JsString::from("\u{41}\n\u{e0001}\n"), 0, false),
                Some(2..4)
            );
        }
        for source in [
            r"[\p{Upper}--A]",
            r"[\p{Upper}&&A]",
            r"[[\p{Upper}]]",
            r"[A-\p{Upper}]",
            r"[\p{Upper}-A]",
            r"[\p{Assigned}]",
        ] {
            assert!(
                RegExpUnicodeClassMatcher::compile_with_flags(
                    &JsString::from(source),
                    true,
                    true,
                    false
                )
                .is_none()
            );
        }
        assert!(
            RegExpUnicodeClassMatcher::compile_binary_property_with_flags(
                &JsString::from(r"[\p{Upper}]"),
                true,
                true,
                false
            )
            .is_none()
        );
    }
